import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Shape[] shapes = new Shape[n];
        for (int i = 0; i < n; i++) {
            String kind = sc.next();
            if (kind.equals("circle")) {
                shapes[i] = new Circle(sc.nextDouble());
            } else {
                shapes[i] = new Square(sc.nextDouble());
            }
        }
        double totalPerimeter = 0;
        for (int i = 0; i < n; i++) {
            System.out.printf(shapes[i].label() + " area: %.2f%n", shapes[i].area());
            totalPerimeter += shapes[i].perimeter();
        }
        System.out.printf("Total perimeter: %.2f%n", totalPerimeter);
    }
}

interface Shape {
    double area();

    double perimeter();

    String label();
}

class Circle implements Shape {
    double r;

    Circle(double r) {
        this.r = r;
    }

    public double area() {
        return Math.PI * r * r;
    }

    public double perimeter() {
        return 2 * Math.PI * r;
    }

    public String label() {
        return "Circle";
    }
}

class Square implements Shape {
    double s;

    Square(double s) {
        this.s = s;
    }

    public double area() {
        return s * s;
    }

    public double perimeter() {
        return 4 * s;
    }

    public String label() {
        return "Square";
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Executive[] team = new Executive[n];
        for (int i = 0; i < n; i++) {
            int role = sc.nextInt();
            String name = sc.next();
            int basePay = sc.nextInt();
            int teamBonus = sc.nextInt();
            int stockAward = sc.nextInt();
            if (role == 1) {
                team[i] = new Executive(name, basePay);
            } else if (role == 2) {
                team[i] = new Manager(name, basePay, teamBonus);
            } else {
                team[i] = new Director(name, basePay, teamBonus, stockAward);
            }
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            int p = team[i].pay();
            System.out.println("Name: " + team[i].name + " Pay: " + p);
            total += p;
        }
        System.out.println("Total: " + total);
    }
}

